# GR13 (Blender background): the approved Garand arms rig (gar_peep.blend: BG4's M24 arms carrying the Realistic M1 Garand,
# regenerated by boltgun_preview_gr.py, the round peep by arms_peep_thin.py) made ready for tools/modern_guns_anim.py, the
# way E:/nmk/kf2/rig/kar_prep.py readied the Kar98k (KR1):
#  - the rifle's pieces named (gar_body, gar_oprod, gar_bolt, gar_follower) and the props (gar_clip, gar_clipround,
#    gar_round0 / 1: the top-up's two rounds); everything BG4 hides throughout left out
#  - a fire clip appended at 195-204: frame 1's pose held, the operating rod and the bolt stroked as in the approved take
#    (back on the shot's next frame, half on the one after, home by the third)
#  - the sights on the rifle (Garand001 local, muzzle -z, up -y): the peep's centre (<in>.peep.json), the front blade's tip,
#    the muzzle; written as srcPoints (the source's glTF-style world: x, z, -y)
#  - the preview camera's look-down in the reloads and the approved take's handheld motion (gr_handheld.py: eased in and out
#    at each reload's ends, so the held idle and the fire clip stay still) moved into the rig (a root bone over the arms, an
#    empty over the rifle and the props), as kar_prep.py does
#  - <out>.json: keep / rigidify / gun / srcPoints / srcScale / hipRear / timeline / clips for the bake config
#   blender -b --factory-startup --disable-autoexec --python gar_prep.py -- <gar_peep.blend> <out.blend>
import bpy, sys, os, json, math
from mathutils import Vector, Matrix
sys.path.insert(0, os.path.dirname(__file__)); import gr_handheld
A = sys.argv[sys.argv.index('--') + 1:]; IN, OUT = A[0], A[1]
bpy.ops.wm.open_mainfile(filepath=IN)
sc = bpy.context.scene; vl = bpy.context.view_layer; ob = bpy.data.objects
K = 1.221 / 1.092                                    # rig units per metre (rig_scene.py)
SEG = json.load(open(os.path.join(os.path.dirname(IN), 'bg', 'gar_segments.json'))) if os.path.exists(os.path.join(os.path.dirname(IN), 'bg', 'gar_segments.json')) else {'segments': [['top-up', 1, 93], ['en-bloc', 108, 180]], 'last': 194}
LAST = SEG['last']; TOPUP = (1, 93); ENBLOC = (108, LAST)   # the en-bloc clip runs on to the rig's settle (the approved take: 108-194)
F0, F1 = LAST + 1, LAST + 10                         # the fire clip
# ---- names
REN = {'Garand001_03 - Default_0': 'gar_body', 'Charging_Handle_02 - Default_0': 'gar_oprod', 'Bolt_02 - Default_0': 'gar_bolt',
       'Recieve_02 - Default_0': 'gar_follower', 'gclip_static': 'gar_clip', 'gbul_static': 'gar_clipround', 'round0': 'gar_round0', 'round1': 'gar_round1'}
for a, b in REN.items(): ob[a].name = b
for m in ob['armmesh'].data.materials:   # the bake's mats key (c4dArms) is 'arms', as the Kar98k's
    if m.name.startswith('arms') and m.name != 'arms': m.name = 'arms'
assert [m.name for m in ob['armmesh'].data.materials] == ['arms'], [m.name for m in ob['armmesh'].data.materials]
rig = list(REN.values())
# ---- sights (Garand001 local) -> the bake's source frame
g = ob['Garand001']; sc.frame_set(1); vl.update(); G = g.matrix_world.copy()
pj = IN + '.peep.json'; cx, cy = json.load(open(pj))['centre'] if os.path.exists(pj) else (-0.0031, -9.1615)
loc = {'rear': (cx, cy, 8.31), 'front': (0.0, -9.15, -21.10), 'muzzle': (0.0, -7.8, -22.5), 'up': (cx, cy - 5.0, 8.31)}
W = {k: G @ Vector(v) for k, v in loc.items()}
src = {k: [round(v.x, 6), round(v.z, 6), round(-v.y, 6)] for k, v in W.items()}
# ---- the fire clip: frame 1's pose held over 195-204 (the armature, the rifle's root, the props), the rod and bolt stroked
arm = ob['Armature']; gun_root = ob['sniper']
P1 = {pb.name: (pb.location.copy(), pb.rotation_quaternion.copy() if pb.rotation_mode == 'QUATERNION' else pb.rotation_euler.copy(), pb.scale.copy()) for pb in arm.pose.bones}
R1 = gun_root.matrix_basis.copy()
take = {n: ob[n] for n in ('Charging_Handle', 'Bolt')}
sc.frame_set(1); closed = {n: o.matrix_basis.copy() for n, o in take.items()}
sc.frame_set(145); opened = {n: o.matrix_basis.copy() for n, o in take.items()}   # the en-bloc's held-open frame (the rod fully back)
stroke = {F0: 0.0, F0 + 1: 1.0, F0 + 2: 0.5, F0 + 3: 0.0}                          # back on the shot's next frame, half, home
props = [ob[n] for n in ('gar_clip', 'gar_clipround', 'gar_round0', 'gar_round1')]
for f in range(F0, F1 + 1):
    for pb in arm.pose.bones:
        l, r, s_ = P1[pb.name]; pb.location = l; pb.scale = s_
        if pb.rotation_mode == 'QUATERNION': pb.rotation_quaternion = r
        else: pb.rotation_euler = r
        for p in ('location', 'rotation_quaternion' if pb.rotation_mode == 'QUATERNION' else 'rotation_euler', 'scale'): pb.keyframe_insert(p, frame=f)
    gun_root.matrix_basis = R1; gun_root.keyframe_insert('location', frame=f); gun_root.keyframe_insert('rotation_euler' if gun_root.rotation_mode != 'QUATERNION' else 'rotation_quaternion', frame=f)
    u = stroke.get(f, 0.0)
    for n, o in take.items():
        a_, b_ = closed[n], opened[n]
        o.matrix_basis = Matrix.LocRotScale(a_.to_translation().lerp(b_.to_translation(), u), a_.to_quaternion().slerp(b_.to_quaternion(), u), a_.to_scale())
        o.keyframe_insert('location', frame=f); o.keyframe_insert('rotation_quaternion' if o.rotation_mode == 'QUATERNION' else 'rotation_euler', frame=f)
    for o in props: o.hide_render = True; o.keyframe_insert('hide_render', frame=f)
sc.frame_end = F1
# ---- the camera's look-down and the handheld motion into the rig (kar_prep.py's camfix / cam_root)
cam = ob['fpcam']; sc.frame_set(1); vl.update(); C0 = cam.matrix_world.copy()
Rc = C0.inverted() @ W['rear']; hip = [round(Rc.x / K, 4), round(-Rc.z / K, 4), round(Rc.y / K, 4)]   # x right, forward, up (m)
fix = bpy.data.objects.new('camfix', None); sc.collection.objects.link(fix)
for o in [gun_root] + [o for o in props if o.parent is None]:
    o.parent = fix; o.matrix_parent_inverse = Matrix()
vl.objects.active = arm; bpy.ops.object.mode_set(mode='EDIT')
rb = arm.data.edit_bones.new('cam_root'); rb.head = (0, 0, 0); rb.tail = (0, 0.1, 0); rb.roll = 0
for e in arm.data.edit_bones:
    if e.parent is None and e.name != 'cam_root': e.use_connect = False; e.parent = rb
bpy.ops.object.mode_set(mode='OBJECT')
pr = arm.pose.bones['cam_root']; pr.rotation_mode = 'QUATERNION'; Aw = arm.matrix_world.copy()
ad = arm.animation_data; assert ad and ad.action, 'no armature action'
def ease(f, a, b, n=10): return min(1.0, (f - a) / n, (b - f) / n) if a <= f <= b else 0.0
def ss(x): x = max(0.0, min(1.0, x)); return x * x * (3 - 2 * x)
EV = [((140 - 107) / 30.0, 1.0), ((156 - 107) / 30.0, 1.6)]   # the take's knocks: the clip driven home (140), the rod slammed forward (156)
mx = 0.0
for f in range(1, F1 + 1):
    sc.frame_set(f); vl.update()
    if TOPUP[0] <= f <= TOPUP[1]: t, w, ev = f / 30.0, ss(ease(f, *TOPUP)), []
    elif ENBLOC[0] <= f <= ENBLOC[1]: t, w, ev = (f - 107) / 30.0, ss(ease(f, *ENBLOC)), EV
    else: t, w, ev = 0.0, 0.0, []
    Ch, Rr, Tr = gr_handheld.handheld(t, w, ev, K)
    T = C0 @ Matrix.Translation(Tr) @ Rr @ Ch.inverted() @ cam.matrix_world.inverted()   # the rig as the preview's (shaken) camera saw it
    if f >= F0: T = Matrix()   # the fire clip: the hold, no camera turn
    mx = max(mx, T.to_quaternion().angle)
    fix.matrix_world = T; fix.keyframe_insert('location', frame=f); fix.keyframe_insert('rotation_euler', frame=f)
    pr.matrix = Aw.inverted() @ T @ Aw @ pr.bone.matrix_local
    for k in ('location', 'rotation_quaternion'): pr.keyframe_insert(k, frame=f)
# ---- checks: the fire clip's pose is the idle's (no jump into or out of a shot); the rod moves in it
sc.frame_set(1); vl.update(); a1 = {n: (ob[n].matrix_world.copy()) for n in ('gar_body', 'armmesh')}; o1 = ob['gar_oprod'].matrix_world.copy()
sc.frame_set(F0 + 4); vl.update(); dmax = max(max(abs(x - y) for ra, rb in zip(ob[n].matrix_world, a1[n]) for x, y in zip(ra, rb)) for n in a1)
sc.frame_set(F0 + 1); vl.update(); stroke_len = (ob['gar_oprod'].matrix_world.translation - o1.translation).length / K
assert dmax < 1e-4, 'fire clip pose differs from the idle by %g' % dmax
assert stroke_len > 0.03, 'the rod does not move in the fire clip (%g m)' % stroke_len
cfg = {'keep': ['armmesh'] + rig, 'rigidify': rig, 'gun': 'gar_body', 'srcPoints': src, 'srcScale': round(1.0 / K, 7), 'hipRear': hip,
       'timeline': [1, F1], 'clips': {'idle': [1, 1], 'fire': [F0, F1], 'reload': list(TOPUP), 'reload_empty': list(ENBLOC)},
       'camTurnMaxDeg': round(math.degrees(mx), 1), 'rodStroke_m': round(stroke_len, 4), 'armsMat': [m.name for m in ob['armmesh'].data.materials]}
json.dump(cfg, open(OUT.replace('.blend', '.json'), 'w'), indent=1); print('GR13 cfg', json.dumps(cfg))
bpy.ops.wm.save_as_mainfile(filepath=OUT)
